namespace sv_5040f4b704e34522891b9c28d8791d3f.Services;

public interface IAppointmentService
{
    Task<List<string>> GetDoctorsAsync();
    Task<List<string>> GetAvailableTimeSlotsAsync(string doctor, DateOnly date);
    Task<Dictionary<string, List<string>>> ValidatePatientAsync(
        string email, string insuranceProvider, string doctor, string timeSlot);
    Task<bool> BookAppointmentAsync(AppointmentRequest request);
}

public class AppointmentRequest
{
    public string PatientName { get; set; } = "";
    public string Email { get; set; } = "";
    public string Phone { get; set; } = "";
    public string InsuranceProvider { get; set; } = "";
    public string PreferredDoctor { get; set; } = "";
    public DateOnly AppointmentDate { get; set; }
    public string TimeSlot { get; set; } = "";
    public string ReasonForVisit { get; set; } = "";
}

namespace sv_5040f4b704e34522891b9c28d8791d3f.Services;

public class AppointmentService : IAppointmentService
{
    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(new List<string>
        {
            "Dr. Smith",
            "Dr. Johnson",
            "Dr. Williams",
            "Dr. Brown"
        });
    }

    public Task<List<string>> GetAvailableTimeSlotsAsync(string doctor, DateOnly date)
    {
        var slots = new List<string>
        {
            "9:00 AM",
            "9:30 AM",
            "10:00 AM",
            "10:30 AM",
            "11:00 AM",
            "1:00 PM",
            "1:30 PM",
            "2:00 PM",
            "2:30 PM",
            "3:00 PM"
        };

        return Task.FromResult(slots);
    }

    public Task<Dictionary<string, List<string>>> ValidatePatientAsync(
        string email, string insuranceProvider, string doctor, string timeSlot)
    {
        var errors = new Dictionary<string, List<string>>();

        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors[nameof(AppointmentFormModel.Email)] = new List<string>
            {
                "Account has outstanding balance"
            };
        }

        if (string.Equals(insuranceProvider, "None", StringComparison.Ordinal)
            && string.Equals(doctor, "Dr. Smith", StringComparison.Ordinal))
        {
            errors[nameof(AppointmentFormModel.PreferredDoctor)] = new List<string>
            {
                "Selected doctor does not accept self-pay patients"
            };
        }

        if (string.Equals(timeSlot, "10:00 AM", StringComparison.Ordinal))
        {
            errors[nameof(AppointmentFormModel.TimeSlot)] = new List<string>
            {
                "This slot is no longer available"
            };
        }

        return Task.FromResult(errors);
    }

    public Task<bool> BookAppointmentAsync(AppointmentRequest request)
    {
        return Task.FromResult(true);
    }
}

