@page "/book-appointment"
@rendermode InteractiveServer
@using sv_5040f4b704e34522891b9c28d8791d3f.Services
@inject IAppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h1>Book a Medical Appointment</h1>

@if (isBooked)
{
    <div class="alert alert-success">
        <h4>Appointment Confirmed!</h4>
        <p>Your appointment with @Model.PreferredDoctor on @Model.AppointmentDate?.ToString("D") at @Model.TimeSlot has been booked.</p>
    </div>
}
else
{
    <EditForm EditContext="editContext" OnSubmit="HandleSubmit" FormName="book-appointment">
        <DataAnnotationsValidator />
        <CustomValidator @ref="customValidator" />

        <h3>Step 1: Patient Information</h3>

        <div class="mb-3">
            <label class="form-label">Patient Name</label>
            <InputText class="form-control" @bind-Value="Model.PatientName" />
            <ValidationMessage For="() => Model.PatientName" />
        </div>

        <div class="mb-3">
            <label class="form-label">Email</label>
            <InputText class="form-control" @bind-Value="Model.Email" />
            <ValidationMessage For="() => Model.Email" />
        </div>

        <div class="mb-3">
            <label class="form-label">Phone</label>
            <InputText class="form-control" @bind-Value="Model.Phone" />
            <ValidationMessage For="() => Model.Phone" />
        </div>

        <div class="mb-3">
            <label class="form-label">Insurance Provider</label>
            <InputSelect class="form-select" @bind-Value="Model.InsuranceProvider">
                <option value="">-- Select Insurance --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => Model.InsuranceProvider" />
        </div>

        @if (!showStep2)
        {
            <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
                Next: Select Appointment
            </button>
        }

        @if (showStep2)
        {
            <hr />
            <h3>Step 2: Appointment Details</h3>

            <div class="mb-3">
                <label class="form-label">Preferred Doctor</label>
                <InputSelect class="form-select" @bind-Value="Model.PreferredDoctor"
                             @bind-Value:after="OnDoctorOrDateChanged">
                    <option value="">-- Select Doctor --</option>
                    @foreach (var doctor in doctors)
                    {
                        <option value="@doctor">@doctor</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.PreferredDoctor" />
            </div>

            <div class="mb-3">
                <label class="form-label">Appointment Date</label>
                <InputDate class="form-control" @bind-Value="Model.AppointmentDate"
                           @bind-Value:after="OnDoctorOrDateChanged" />
                <ValidationMessage For="() => Model.AppointmentDate" />
            </div>

            <div class="mb-3">
                <label class="form-label">Time Slot</label>
                <InputSelect class="form-select" @bind-Value="Model.TimeSlot">
                    <option value="">-- Select Time Slot --</option>
                    @foreach (var slot in timeSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.TimeSlot" />
            </div>

            <div class="mb-3">
                <label class="form-label">Reason for Visit</label>
                <InputTextArea class="form-control" @bind-Value="Model.ReasonForVisit" rows="4" />
                <ValidationMessage For="() => Model.ReasonForVisit" />
            </div>

            <button type="button" class="btn btn-secondary me-2" @onclick="CheckAvailability"
                    disabled="@isProcessing">
                @(isProcessing ? "Checking..." : "Check Availability")
            </button>

            <button type="submit" class="btn btn-success" disabled="@(!availabilityConfirmed || isProcessing)">
                Book Appointment
            </button>

            @if (availabilityConfirmed)
            {
                <div class="alert alert-info mt-3">
                    ✓ Availability confirmed. You may now book your appointment.
                </div>
            }
        }
    </EditForm>
}

@code {
    private AppointmentFormModel Model { get; set; } = new();
    private EditContext? editContext;
    private CustomValidator? customValidator;

    private List<string> doctors = new();
    private List<string> timeSlots = new();
    private bool showStep2;
    private bool isBooked;
    private bool isProcessing;
    private bool availabilityConfirmed;

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(Model);
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Validate only step 1 fields
        var isValid = true;
        editContext!.NotifyFieldChanged(editContext.Field(nameof(Model.PatientName)));
        editContext.NotifyFieldChanged(editContext.Field(nameof(Model.Email)));
        editContext.NotifyFieldChanged(editContext.Field(nameof(Model.Phone)));
        editContext.NotifyFieldChanged(editContext.Field(nameof(Model.InsuranceProvider)));

        var messages = editContext.GetValidationMessages();
        // Check only step 1 fields for errors
        var step1Fields = new[]
        {
            nameof(Model.PatientName), nameof(Model.Email),
            nameof(Model.Phone), nameof(Model.InsuranceProvider)
        };

        foreach (var field in step1Fields)
        {
            var fieldIdentifier = editContext.Field(field);
            if (editContext.GetValidationMessages(fieldIdentifier).Any())
            {
                isValid = false;
            }
        }

        if (isValid && !string.IsNullOrEmpty(Model.PatientName)
            && !string.IsNullOrEmpty(Model.Email)
            && !string.IsNullOrEmpty(Model.Phone)
            && !string.IsNullOrEmpty(Model.InsuranceProvider))
        {
            showStep2 = true;
        }
    }

    private async Task OnDoctorOrDateChanged()
    {
        availabilityConfirmed = false;
        if (!string.IsNullOrEmpty(Model.PreferredDoctor) && Model.AppointmentDate.HasValue)
        {
            timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
                Model.PreferredDoctor, Model.AppointmentDate.Value);
        }
        else
        {
            timeSlots = new();
        }
        Model.TimeSlot = null;
    }

    private async Task CheckAvailability()
    {
        customValidator?.ClearErrors();
        availabilityConfirmed = false;
        isProcessing = true;

        // Validate step 2 fields client-side first
        var isValid = editContext!.Validate();
        if (!isValid)
        {
            isProcessing = false;
            return;
        }

        var errors = await AppointmentService.ValidatePatientAsync(
            Model.Email!, Model.InsuranceProvider!, Model.PreferredDoctor!, Model.TimeSlot!);

        if (errors.Count > 0)
        {
            customValidator!.DisplayErrors(errors);
            isProcessing = false;
            return;
        }

        availabilityConfirmed = true;
        isProcessing = false;
    }

    private async Task HandleSubmit()
    {
        if (!availabilityConfirmed)
            return;

        var isValid = editContext!.Validate();
        if (!isValid)
            return;

        var request = new AppointmentRequest
        {
            PatientName = Model.PatientName!,
            Email = Model.Email!,
            Phone = Model.Phone!,
            InsuranceProvider = Model.InsuranceProvider!,
            PreferredDoctor = Model.PreferredDoctor!,
            AppointmentDate = Model.AppointmentDate!.Value,
            TimeSlot = Model.TimeSlot!,
            ReasonForVisit = Model.ReasonForVisit!
        };

        await AppointmentService.BookAppointmentAsync(request);
        isBooked = true;
    }
}

